<script setup lang="ts">
import { ref, watch } from 'vue'
import WorkspaceHeader from '../components/WorkspaceHeader.vue'
import ReportPanels from '../components/ReportPanels.vue'
import { useWorkspace } from '../composables/useWorkspace'
import { workspaceApi } from '../api/workspace'
import * as sample from '../api/preview'
import { errorMessage } from '../api/client'
import type { Dashboard, Report } from '../types/workspace'
const { courseId, preview, loading, error, run } = useWorkspace(), data = ref<Dashboard>(), drawer = ref(false), studentId = ref(''), studentName = ref(''), report = ref<Report>(), detailBusy = ref(false), detailError = ref(''), triggerBusy = ref(false)
function load() { data.value = undefined; drawer.value = false; void run(() => preview.value ? Promise.resolve(sample.dashboard) : workspaceApi.dashboard(courseId.value), value => data.value = value) }
watch(preview, load, { immediate: true })
async function openStudent(id: string, name: string) { studentId.value = id; studentName.value = name; drawer.value = true; report.value = undefined; detailBusy.value = true; detailError.value = ''; try { report.value = preview.value ? sample.report : await workspaceApi.student(courseId.value, id) } catch (e) { detailError.value = errorMessage(e) } finally { detailBusy.value = false } }
async function diagnose() { triggerBusy.value = true; try { if (preview.value) { detailError.value = '界面预览不创建诊断任务。'; return }; const job = await workspaceApi.diagnose(courseId.value, studentId.value); detailError.value = `诊断任务已受理：${job.job_id}，请稍后重新打开学生详情。` } catch (e) { detailError.value = errorMessage(e) } finally { triggerBusy.value = false } }
</script>
<template><WorkspaceHeader :course-id="courseId" title="教师学情看板" v-model:preview="preview" :loading="loading || detailBusy || triggerBusy" :error="error" @reload="load" /><div v-loading="loading"><el-empty v-if="!data" description="暂无学情统计" /><template v-else><div class="metric-grid"><section class="panel" v-for="metric in [{ label:'课程人数',value:data.student_count },{label:'活跃人数',value:data.active_count},{label:'资源完成率',value:data.completion+'%'},{label:'平均分',value:data.average_score}]" :key="metric.label"><p>{{ metric.label }}</p><strong class="metric-value">{{ metric.value }}</strong></section></div><section class="panel"><h2>知识点掌握度</h2><p class="muted">点击学生或单元格查看诊断、学习记录与证据。颜色越深表示掌握度越高。</p><div class="table-scroll"><table class="mastery-table"><thead><tr><th>学生</th><th v-for="kp in data.knowledge_points" :key="kp">{{ kp }}</th><th>风险</th></tr></thead><tbody><tr v-for="s in data.students" :key="s.id"><td><el-button text :disabled="detailBusy" @click="openStudent(s.id,s.name)">{{ s.name }}</el-button></td><td v-for="(kp,i) in data.knowledge_points" :key="kp"><button class="heat-cell" :disabled="detailBusy" :style="{ background: `rgba(25,120,100,${(s.mastery[i] ?? 0)/160 + 0.1})` }" @click="openStudent(s.id,s.name)">{{ s.mastery[i] ?? '—' }}%</button></td><td>{{ s.risk }}</td></tr></tbody></table></div><el-empty v-if="!data.students.length" description="暂无学生数据" /></section><div class="learning-grid followup-panel"><section class="panel"><h2>题目统计</h2><el-table :data="data.questions"><el-table-column prop="stem" label="题目" /><el-table-column label="正确率"><template #default="s">{{ s.row.correct_rate }}%</template></el-table-column><el-table-column prop="average_seconds" label="平均用时（秒）" /><el-table-column label="选项人数"><template #default="s">{{ Object.entries(s.row.option_counts).map(([k,v]) => `${k}: ${v}`).join(' / ') }}</template></el-table-column></el-table></section><section class="panel"><h2>分数分布</h2><div v-for="bucket in data.score_distribution" :key="bucket.label"><p>{{ bucket.label }} 分 · {{ bucket.count }} 人</p><el-progress :percentage="Math.round(bucket.count / Math.max(1,data.student_count) * 100)" /></div></section></div></template></div><el-drawer v-model="drawer" :title="studentName + ' · 学习详情'" size="min(720px, 96vw)"><div v-loading="detailBusy"><el-alert v-if="detailError" :title="detailError" :closable="false" /><el-button type="primary" :loading="triggerBusy" :disabled="detailBusy" @click="diagnose">手动触发诊断</el-button><ReportPanels v-if="report" :report="report" /><el-empty v-else-if="!detailBusy" description="暂无学生报告" /></div></el-drawer></template>
